package br.com.gestao.finance; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="financial_entries") public class FinancialEntry{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Enumerated(EnumType.STRING) @Column(nullable=false) private EntryType type; @Column(nullable=false,length=80) private String category; @Column(nullable=false,length=180) private String description; @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; private LocalDate dueDate; @Column(nullable=false) private boolean paid; @Column(nullable=false) private LocalDateTime createdAt; private String createdBy; public FinancialEntry(){} public FinancialEntry(Long id,EntryType type,String category,String description,BigDecimal amount,LocalDate dueDate,boolean paid,LocalDateTime createdAt,String createdBy){this.id=id;this.type=type;this.category=category;this.description=description;this.amount=amount;this.dueDate=dueDate;this.paid=paid;this.createdAt=createdAt;this.createdBy=createdBy;} public Long getId(){return id;} public EntryType getType(){return type;} public void setType(EntryType v){type=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public LocalDate getDueDate(){return dueDate;} public void setDueDate(LocalDate v){dueDate=v;} public boolean isPaid(){return paid;} public void setPaid(boolean v){paid=v;} public LocalDateTime getCreatedAt(){return createdAt;} public String getCreatedBy(){return createdBy;}}
